class Solution {
public:
    long long minimumTime(vector<int>& time, int totalTrips) {
        long long minT = *min_element(time.begin(), time.end());
        long long low = 1, high = minT * totalTrips;
        while (low < high) {
            long long mid = low + (high - low) / 2;
            long long trips = 0;
            for (int t : time) trips += mid / t;
            if (trips >= totalTrips) high = mid;
            else low = mid + 1;
        }
        return low;
    }
};

class Solution {
    public long minimumTime(int[] time, int totalTrips) {
        long minT = time[0];
        for (int t : time) if (t < minT) minT = t;
        long low = 1, high = minT * totalTrips;
        while (low < high) {
            long mid = low + (high - low) / 2;
            long trips = 0;
            for (int t : time) trips += mid / t;
            if (trips >= totalTrips) high = mid;
            else low = mid + 1;
        }
        return low;
    }
}

var minimumTime = function(time, totalTrips) {
    let minT = Infinity;
    for (const t of time) if (t < minT) minT = t;
    let low = 1n, high = BigInt(minT) * BigInt(totalTrips);
    const req = BigInt(totalTrips);
    while (low < high) {
        const mid = (low + high) / 2n;
        let trips = 0n;
        for (const t of time) trips += mid / BigInt(t);
        if (trips >= req) high = mid;
        else low = mid + 1n;
    }
    return Number(low);
};
